use super::*;
use std::fs;
use std::path::PathBuf;
use crate::local_database::joint_archive::tests::genuine_import_owner_fixture;
fn local()->Value{json!({"version":1,"serverBase":"http://local-settings.invalid","accountId":"local-user","sessionId":"11111111-1111-1111-1111-111111111111","cacheScope":"local-archive-11111111-1111-1111-1111-111111111111","storageMode":"local","provider":"none"})}
fn current(selection:vault::SnapshotRequestBinding)->Current{Current::capture(selection,"none",local()).unwrap()}
fn selected(result:&Value)->AssetSelection{let asset=&result["candidate"]["assets"][0];AssetSelection{space_id:asset["space_id"].as_str().unwrap().into(),document_id:asset["document_id"].as_str().unwrap().into(),asset_id:asset["id"].as_str().unwrap().into()}}
#[tokio::test]async fn actual_initialized_descriptor_ignores_stale_json_and_preview_resolves_destination_receipt(){let _g=vault::archive_admission::TEST_SERIAL.lock().unwrap_or_else(|e|e.into_inner());let(root,selection,_,_,result)=genuine_import_owner_fixture(196608).await;fs::write(root.join("new-vault/vault.json"),b"{foreign mirror}").unwrap();let descriptor=current(selection.clone()).run(local(),None,None,0,0).await.unwrap();assert_eq!(descriptor["serve_authority"],false);assert_eq!(descriptor["export_authority"],false);assert_eq!(descriptor["binding"]["root"],json!(root.join("new-vault")));let preview=current(selection).run(local(),Some(selected(&result)),Some(descriptor["binding"].clone()),65536,65536).await.unwrap();assert_eq!(preview["bytes"],json!(vec![7u8;65536]));assert_eq!(preview["byte_length"],196608);assert_eq!(preview["raw_version_record"],result["candidate"]["assets"][0]["server_version_provenance"]["raw_version_record"]);fs::remove_dir_all(root).unwrap();}
#[tokio::test]async fn descriptor_context_and_original_revision_range_page_refuse(){let _g=vault::archive_admission::TEST_SERIAL.lock().unwrap_or_else(|e|e.into_inner());let(root,selection,_,_,result)=genuine_import_owner_fixture(7).await;let descriptor=current(selection.clone()).run(local(),None,None,0,0).await.unwrap();let mut wrong=local();wrong["sessionId"]=json!("other");assert!(current(selection.clone()).run(wrong,None,None,0,0).await.is_err());let mut prior=descriptor["binding"].clone();prior["revision"]=json!("stale");assert!(current(selection.clone()).run(local(),Some(selected(&result)),Some(prior),0,7).await.unwrap_err().contains("binding changed"));assert!(current(selection.clone()).run(local(),Some(selected(&result)),Some(descriptor["binding"].clone()),0,65537).await.is_err());assert!(current(selection.clone()).run(local(),Some(selected(&result)),Some(descriptor["binding"].clone()),6,2).await.is_err());let mut page=selected(&result);page.document_id="other".into();assert!(current(selection.clone()).run(local(),Some(page),Some(descriptor["binding"].clone()),0,7).await.is_err());let held=current(selection);fs::write(root.join("new-settings.json"),json!({"vault_path":root.join("foreign")}).to_string()).unwrap();assert!(held.run(local(),None,None,0,0).await.is_err());assert!(!root.join("foreign").exists());fs::remove_dir_all(root).unwrap();}
#[tokio::test]async fn imported_consumer_equal_content_foreign_inode_refuses(){let _g=vault::archive_admission::TEST_SERIAL.lock().unwrap_or_else(|e|e.into_inner());let(root,selection,_,_,result)=genuine_import_owner_fixture(7).await;let descriptor=current(selection.clone()).run(local(),None,None,0,0).await.unwrap();let target=PathBuf::from(result["candidate"]["assets"][0]["vault_path"].as_str().unwrap());let held=target.with_extension("held");fs::rename(&target,&held).unwrap();fs::copy(held,target).unwrap();assert!(current(selection).run(local(),Some(selected(&result)),Some(descriptor["binding"].clone()),0,7).await.is_err());fs::remove_dir_all(root).unwrap();}
#[tokio::test]async fn descriptor_missing_database_never_creates_source(){let work=std::env::temp_dir().join(format!("native-context-missing-{}",std::process::id()));fs::create_dir_all(&work).unwrap();let missing=work.join("not-created");let selection=vault::SnapshotRequestBinding::capture_at(work.join("settings.json"),missing.clone(),"none").unwrap();assert!(Current::capture(selection,"none",local()).is_err());assert!(!missing.exists());fs::remove_dir_all(work).unwrap();}
#[tokio::test(flavor="multi_thread",worker_threads=2)]#[ignore="fresh actual IPC worker"]async fn fresh_ipc_worker(){let work=PathBuf::from(std::env::var("STARLANE_ARCHIVE_CONTEXT_FIXTURE").expect("private fixture required"));let input:Value=serde_json::from_slice(&fs::read(work.join("context-input.json")).unwrap()).unwrap();let app=tauri::test::mock_builder().plugin(tauri_plugin_store::Builder::new().build()).invoke_handler(tauri::generate_handler![describe_current_native_vault_archive,read_imported_native_attachment_preview]).build(tauri::test::mock_context(tauri::test::noop_assets())).unwrap();let path=tauri_plugin_store::resolve_store_path(app.handle(),"settings.json").unwrap();assert!(path.starts_with(&work));fs::create_dir_all(path.parent().unwrap()).unwrap();fs::write(path,json!({"vault_path":work.join("new-vault")}).to_string()).unwrap();let window=tauri::WebviewWindowBuilder::new(&app,"context-worker",Default::default()).build().unwrap();let call=|cmd:&str,body:Value|tauri::test::get_ipc_response(&window,tauri::webview::InvokeRequest{cmd:cmd.into(),callback:tauri::ipc::CallbackFn(0),error:tauri::ipc::CallbackFn(1),url:"http://tauri.localhost".parse().unwrap(),body:tauri::ipc::InvokeBody::Json(body),headers:Default::default(),invoke_key:tauri::test::INVOKE_KEY.into()});let descriptor:Value=call("describe_current_native_vault_archive",json!({"provider":"none","context":local(),"current":local()})).unwrap().deserialize().unwrap();let preview:Value=call("read_imported_native_attachment_preview",json!({"provider":"none","context":local(),"current":local(),"originalBinding":descriptor["binding"],"selection":input["selection"],"offset":0,"length":65536})).unwrap().deserialize().unwrap();assert_eq!(preview["bytes"],json!(vec![7u8;65536]));assert_eq!(preview["raw_version_record"],input["raw_version"]);assert_eq!(descriptor["export_authority"],false);println!("ACTUAL_FRESH_PROCESS_CANONICAL_DESCRIPTOR_IMPORTED_OWNER_PREVIEW_IPC_PASS");}
#[tokio::test(flavor="multi_thread",worker_threads=2)]async fn genuine_import_restart_actual_ipc_keeps_raw_receipt_and_current_owner(){let _g=vault::archive_admission::TEST_SERIAL.lock().unwrap_or_else(|e|e.into_inner());let(work,_,_,_,result)=genuine_import_owner_fixture(196608).await;let asset=&result["candidate"]["assets"][0];fs::write(work.join("context-input.json"),json!({"selection":{"space_id":asset["space_id"],"document_id":asset["document_id"],"asset_id":asset["id"]},"raw_version":asset["server_version_provenance"]["raw_version_record"]}).to_string()).unwrap();let mut child=std::process::Command::new(std::env::current_exe().unwrap());child.args(["local_database::attachment_download_owner::native_archive_context::tests::fresh_ipc_worker","--exact","--ignored","--nocapture"]).env("STARLANE_ARCHIVE_CONTEXT_FIXTURE",&work);for(key,name)in[("XDG_CONFIG_HOME","config"),("XDG_DATA_HOME","data"),("XDG_CACHE_HOME","cache"),("XDG_STATE_HOME","state")]{let path=work.join(name);fs::create_dir_all(&path).unwrap();child.env(key,path);}let response=child.output().unwrap();assert!(response.status.success(),"{} {}",String::from_utf8_lossy(&response.stdout),String::from_utf8_lossy(&response.stderr));assert!(String::from_utf8_lossy(&response.stdout).contains("ACTUAL_FRESH_PROCESS_CANONICAL_DESCRIPTOR_IMPORTED_OWNER_PREVIEW_IPC_PASS"));fs::remove_dir_all(work).unwrap();}

#[tokio::test]#[ignore="actual genuine 100MiB imported owner consumer"]async fn actual_imported_context_preview_100mib(){let _g=vault::archive_admission::TEST_SERIAL.lock().unwrap_or_else(|e|e.into_inner());let(root,selection,_,_,result)=genuine_import_owner_fixture(104857600).await;let descriptor=current(selection.clone()).run(local(),None,None,0,0).await.unwrap();let preview=current(selection).run(local(),Some(selected(&result)),Some(descriptor["binding"].clone()),104857600-65536,65536).await.unwrap();assert_eq!(preview["byte_length"],104857600);assert_eq!(preview["bytes"],json!(vec![7u8;65536]));assert_eq!(preview["raw_version_record"],result["candidate"]["assets"][0]["server_version_provenance"]["raw_version_record"]);println!("ACTUAL_100MIB_GENUINE_IMPORTED_OWNER_CANONICAL_CONTEXT_EXACT_FINAL_64K_PREVIEW_PASS");fs::remove_dir_all(root).unwrap();}

#[tokio::test]async fn original_trash_producer_uses_canonical_rows_and_holds_selected_root_before_wait(){
 let _g=vault::archive_admission::TEST_SERIAL.lock().unwrap_or_else(|e|e.into_inner());let(root,selection,_,_,result)=genuine_import_owner_fixture(7).await;
 let path=root.join("new-vault/.starlane/starlane-notes.sqlite3");let pool=sqlx::sqlite::SqlitePoolOptions::new().max_connections(1).connect_with(sqlx::sqlite::SqliteConnectOptions::new().filename(&path)).await.unwrap();let mut tx=pool.begin().await.unwrap();let mut source=result["candidate"].clone();let page=&mut source["documents"][0];page["created_at"]=json!("exact-birth");page["deleted_at"]=json!("exact-trash");let space=page["space_id"].as_str().unwrap().to_string();crate::local_database::write_snapshot_in_tx(&mut tx,"none",&source).await.unwrap();tx.commit().await.unwrap();pool.close().await;
 fs::write(root.join("new-vault/starlane-vault-none.json"),b"FOREIGN STALE MIRROR").unwrap();let selected=current(selection.clone());let list=selected.trash(local(),space.clone()).await.unwrap();assert_eq!(list["documents"][0]["created_at"],"exact-birth");assert_eq!(list["documents"][0]["deleted_at"],"exact-trash");assert_eq!(list["binding"]["root"],json!(root.join("new-vault")));assert_eq!(fs::read(root.join("new-vault/starlane-vault-none.json")).unwrap(),b"FOREIGN STALE MIRROR");
 let mut foreign=local();foreign["sessionId"]=json!("foreign");assert!(current(selection.clone()).trash(foreign,space.clone()).await.is_err());
 let held=current(selection);let guard=snapshot_commit_lock().lock().await;let job=tokio::spawn(async move{held.trash(local(),space).await});tokio::task::yield_now().await;
 fs::rename(root.join("new-vault"),root.join("held-vault")).unwrap();fs::create_dir(root.join("new-vault")).unwrap();fs::create_dir(root.join("new-vault/.starlane")).unwrap();fs::copy(root.join("held-vault/.starlane/starlane-notes.sqlite3"),root.join("new-vault/.starlane/starlane-notes.sqlite3")).unwrap();drop(guard);assert!(job.await.unwrap().is_err());fs::remove_dir_all(root).unwrap();
}
